-- Seed profile photos from docs/Images
-- Each image is attached to the profile matching the filename (case-insensitive)

-- Photo for Adaeze
INSERT INTO dinanwuye_profile."Photo" ("id", "profileId", "s3Key", "order", "moderationStatus", "createdAt")
SELECT
  gen_random_uuid()::text,
  p."id",
  'data:image/jpeg;base64,',
  0,
  'approved',
  now()
FROM dinanwuye_profile."Profile" p
WHERE LOWER(p."name") = LOWER('Adaeze')
AND NOT EXISTS (
  SELECT 1 FROM dinanwuye_profile."Photo" ph WHERE ph."profileId" = p."id"
);

